import * as fs from 'fs';
import * as path from 'path';

// Generated by scripts/build-catalog.js into dist/catalog.
const catalogDir = path.join(__dirname, 'catalog');

export function loadIndex(): ModSummary[] {
  return JSON.parse(fs.readFileSync(path.join(catalogDir, 'index.json'), 'utf8')) as ModSummary[];
}

export function loadGames(): GameDef[] {
  return JSON.parse(fs.readFileSync(path.join(catalogDir, 'games.json'), 'utf8')) as GameDef[];
}

export function loadManifest(id: string): ModManifest | null {
  // Ids come from the renderer, so never let one build an arbitrary path.
  if (!/^[a-z0-9]+(-[a-z0-9]+)*$/.test(id)) return null;
  const file = path.join(catalogDir, 'mods', `${id}.json`);
  if (!fs.existsSync(file)) return null;
  return JSON.parse(fs.readFileSync(file, 'utf8')) as ModManifest;
}

export function loadAllManifests(): ModManifest[] {
  const dir = path.join(catalogDir, 'mods');
  return fs
    .readdirSync(dir)
    .filter((f) => f.endsWith('.json'))
    .map((f) => JSON.parse(fs.readFileSync(path.join(dir, f), 'utf8')) as ModManifest);
}
